//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/json2.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/report.js");
scwin.vScrenID = "ULDSTF05933.xml";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vLstTrdWeekStart = "";
scwin.vLstTrdWeekEnd = "";
scwin.vLstTrdWeekFm = "";
scwin.vLstTrdDd = "";
scwin.vLstTrdDdFm = "";
scwin.vFromCd = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.dateForm = function(pStr) {
    return "'" + pStr.substring(2, 4) + "." + pStr.substring(4, 6) + "." + pStr.substring(6, 8);
};
scwin.dateForm2 = function(pStr) {
    return pStr.substring(4, 6) + "." + pStr.substring(6, 8);
};
scwin.fn_get_trd_read_sync = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=ELW_IMP_VOLT_CALND_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.select.elwimpvolt.lsttrdweek.condition";
    dts_LstWeekTrd.DataID = encodeURI(url);
    dts_LstWeekTrd.reset();
    scwin.vLstTrdWeekStart = dts_LstWeekTrd.getCellData(1, "LST_TRD_WEEK_STRT");
    scwin.vLstTrdWeekEnd = dts_LstWeekTrd.getCellData(1, "LST_TRD_WEEK_END");
    scwin.vLstTrdWeekFm = scwin.dateForm(scwin.vLstTrdWeekStart) + "~" + scwin.dateForm2(scwin.vLstTrdWeekEnd);
    url = "/listingCommon.do?method=listGeneral&outputMessageId=ELW_IMP_VOLT_CALND_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.select.elwimpvolt.lsttrd.condition";
    dts_LstTrd.DataID = encodeURI(url);
    dts_LstTrd.reset();
    scwin.vLstTrdDd = dts_LstTrd.getCellData(1, "LST_TRD_DD");
    scwin.vLstTrdDdFm = scwin.dateForm(scwin.vLstTrdDd);
};
scwin.fn_read_sync = function() {
    if (js_svrGubun == 'dr') {
        $c.win.alert("DR에서 운영될때는 서비스가 제공되지 않습니다.");
        return;
    }
    var vDistrCd = $c.stf.getObjectValue(cmb_DISTR_CD);
    scwin.fn_get_trd_read_sync();
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=ELW_IMP_VOLT_DSCL_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    var str = "";
    if (vDistrCd == '1') {
        scwin.vFromCd = '68960';
        //str = "내재변동성 변동비율 상위종목수 LP별 분포현황 공표";
        str = "LP별 내재변동성의 일관성 분포현황 공표"; //20081023변경
        url += "&queryId=lds.stf.lstproc.select.elwimpvolt.daily.condition";
        url += "&{P}param01=" + scwin.vLstTrdDdFm;
        url += "&{P}param02=" + scwin.vLstTrdDd;
        url += "&{P}param03=" + scwin.vLstTrdDd;
    } else if (vDistrCd == '2') {
        scwin.vFromCd = '68958';
        //str = "발행시점대비 내재변동성 변동비율 상위종목수 LP별 분포현황 공표";
        str = "주간상장종목중 LP별 내재변동성의 일관성 분포현황 공표"; //20081023변경

        url += "&queryId=lds.stf.lstproc.select.elwimpvolt.weekly.condition";
        url += "&{P}param01=" + scwin.vLstTrdWeekFm;
        url += "&{P}param02=" + scwin.vLstTrdWeekEnd;
        url += "&{P}param03=" + scwin.vLstTrdWeekEnd;
    }
    $c.stf.setObjectValue(txb_INFO_TITLE, str);
    dts_Discls.DataID = encodeURI(url);
    dts_Discls.reset();
    var vCtnt = "";
    for (var i = 1; i <= dts_Discls.getTotalRow(); i++) {
        vCtnt += "\r\n";
        vCtnt += dts_Discls.getCellData(i, "TITLE");
    }
    txa_INFO_CONTN.text = vCtnt;
};
scwin.fn_CheckForm = function() {
    if (!$c.stf.checkEmptyValue(txb_INFO_TITLE, "제목")) return false;
    if (!$c.stf.checkMaxLength(txb_INFO_TITLE, 256, "제목")) return false;
    if (!$c.stf.checkEmptyValue(txa_INFO_CONTN, "내용")) return false;
    return true;
};
scwin.fn_dscl = async function() {
    if (!scwin.fn_CheckForm()) return;
    var vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
    if (vBzProcsNo.length != 14) {
        $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        return;
    }
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        arr[0] = scwin.vFromCd;
        arr[1] = vBzProcsNo; //테스트할때는 첫번째 업무처리번호를 일단 넘긴다...
        arr[2] = '99999'; //거래소코드
        arr[3] = '1';
        arr[4] = txa_INFO_CONTN.Text;
        arr[5] = '';

        //CopyDataSet( dts_Delistdetail , param_dts_isu) ;
        //CopyDataSet( dts_Isu , param_dts_mst) ;
        return arr.length;
    };
    scwin.fn_SetPar = function(arr) {

    };
    var wth = 730 + 5;
    var hgt = 785 + 30;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;
};



/********************************************** 
 * 함수명   : Print()
 * 설명       : 화면을 인쇄한다. 
 ***********************************************/
scwin.fn_print = function() {
    var sDepNm_1 = "";
    var sDepNm_2 = "";

    //PDF 리포트 파일명 
    var pdf_rptname = "RLDSTF00004";
    var tInfoContn = txa_INFO_CONTN.text;
    if (tInfoContn != '') {
        tInfoContn = $c.ut.replaceAll(tInfoContn, '\n', '<br>');
        tInfoContn = $c.ut.replaceAll(tInfoContn, ' ', '&nbsp;');
    } else {
        tInfoContn = $c.ut.defaultStrHtmlSpace(tInfoContn);
    }
    var userParam = [{
        uid: "DEP_NM_1",
        unm: $c.ut.defaultStrHtmlSpace(sDepNm_1)
    }, {
        uid: "DEP_NM_2",
        unm: $c.ut.defaultStrHtmlSpace(sDepNm_2)
    }, {
        uid: "ISUR_CD",
        unm: $c.ut.defaultStrHtmlSpace("")
    }, {
        uid: "COM_NM",
        unm: $c.ut.defaultStrHtmlSpace("")
    }, {
        uid: "TITLE",
        unm: $c.stf.getObjectValue(txb_INFO_TITLE)
    }, {
        uid: "BODY",
        unm: tInfoContn
    }];

    //PDF Convert
    $c.rpt.fn_open_report_pdf(pdf_rptname, userParam);
};


/********************************************** 
 * ASIS rexpert-bak 2018-04-03
 * 함수명   : Print()
 * 설명       : 화면을 인쇄한다. 
 ***********************************************/
scwin.fn_print_old = function() {

    //dts_Print.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    //껍데기만 만들고 사용자필드를 사용함
    dts_Print.insertRow();
    //dts_Print.NameValue(1, "TEST") = dtsObj.NameValue(1, "COM_NM");

    //데이타셋 
    //var testDateSet = rex_gfGetGauceCsvStrAll(dts_TempPrint, MxDataSet_emp_data );
    var testDateSet = rex_gfGetGauceCsvStr(dts_Print);
    //alert('[testDateSet]'+testDateSet);

    //Rexpert리포트 파일명 
    //var rex_rptname = "test/sample4";
    var rex_rptname = "RLDSTF00004";
    var userParam = [{
        uid: "ISUR_CD",
        unm: ""
    }, {
        uid: "COM_NM",
        unm: ""
    }, {
        uid: "TITLE",
        unm: $c.stf.getObjectValue(txb_INFO_TITLE)
    }, {
        uid: "BODY",
        unm: txa_INFO_CONTN.text
    }];

    //Rexpert 미리보기 호출 
    $c.rpt.fn_open_report(testDateSet, rex_rptname, userParam);
};
scwin.cmb_DISTR_CD_OnSelChange = function() {
    scwin.fn_read_sync();
};
scwin.btn_Dscl_onclick = function() {
    scwin.fn_dscl();
};
scwin.btn_Print_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_05);
    if (!scwin.fn_CheckForm()) return;
    scwin.fn_print();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_Discls_OnLoadError = function() {
    $c.stf.alert_error(dts_Discls);
};
scwin.dts_LstTrd_OnLoadError = function() {
    $c.stf.alert_error(dts_LstTrd);
};
scwin.dts_LstWeekTrd_OnLoadError = function() {
    $c.stf.alert_error(dts_LstWeekTrd);
};
scwin.dts_Discls_OnLoadCompleted = function(rowcount) {

};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Item);
    $c.stf.setObjectValue(cmb_DISTR_CD, 1);
};
